// Interior art: floors, wallpapers, wall trim and furniture. Rows are generated by small
// helpers but exported as plain strings.
const G = (w, h) => ({ w, h, g: Array.from({ length: h }, () => Array(w).fill('.')) });
const p = (s, x, y, c) => { if (x >= 0 && y >= 0 && x < s.w && y < s.h) s.g[y][x] = c; };
const f = (s, x, y, w, h, c) => { for (let j = 0; j < h; j++) for (let i = 0; i < w; i++) p(s, x + i, y + j, c); };
// outlined box with optional highlight (top inner row) and shade (bottom inner row)
const ob = (s, x, y, w, h, c, hi, sh) => {
  f(s, x, y, w, h, 'O');
  f(s, x + 1, y + 1, w - 2, h - 2, c);
  if (hi) f(s, x + 1, y + 1, w - 2, 1, hi);
  if (sh) f(s, x + 1, y + h - 2, w - 2, 1, sh);
};
const disc = (s, cx, cy, r, c) => {
  for (let y = -r; y <= r; y++) for (let x = -r; x <= r; x++) if (x * x + y * y <= r * r + r * 0.6) p(s, cx + x, cy + y, c);
};
const odisc = (s, cx, cy, r, c) => { disc(s, cx, cy, r + 1, 'O'); disc(s, cx, cy, r, c); };
const out = (s) => ({ w: s.w, h: s.h, rows: s.g.map((r) => r.join('')) });
const mk = (w, h, fn) => { const s = G(w, h); fn(s); return out(s); };

const sprites = {};
const anims = {};

// ---------- floors (16x16, tileable) ----------
sprites['floor.wood'] = mk(16, 16, (s) => {
  f(s, 0, 0, 16, 16, 'c');
  for (let r = 0; r < 4; r++) {
    const y = r * 4;
    f(s, 0, y, 16, 1, 'b');
    f(s, 0, y + 3, 16, 1, 'd');
    const x = (r * 5 + 3) % 16;
    f(s, x, y, 1, 4, 'd');
    p(s, (x + 7) % 16, y + 1, 'b');
    p(s, (x + 10) % 16, y + 2, 'd');
  }
});
sprites['floor.light'] = mk(16, 16, (s) => {
  f(s, 0, 0, 16, 16, 'a');
  for (let r = 0; r < 4; r++) {
    const y = r * 4;
    f(s, 0, y + 3, 16, 1, 'b');
    const x = (r * 6 + 2) % 16;
    f(s, x, y, 1, 3, 'b');
    p(s, (x + 6) % 16, y + 1, 'b');
  }
});
sprites['floor.tile'] = mk(16, 16, (s) => {
  for (let ty = 0; ty < 2; ty++) for (let tx = 0; tx < 2; tx++) {
    const dark = (tx + ty) % 2;
    f(s, tx * 8, ty * 8, 8, 8, dark ? 't' : 's');
    f(s, tx * 8, ty * 8, 8, 1, dark ? 's' : 'W');
    f(s, tx * 8 + 7, ty * 8, 1, 8, 'u');
    f(s, tx * 8, ty * 8 + 7, 8, 1, 'u');
  }
});
sprites['floor.carpet'] = mk(16, 16, (s) => {
  f(s, 0, 0, 16, 16, 'm');
  for (let y = 0; y < 16; y += 4) for (let x = 0; x < 16; x += 4) {
    p(s, x + ((y / 4) % 2) * 2, y, 'n');
    p(s, x + ((y / 4) % 2) * 2, y + 1, 'W');
  }
  f(s, 0, 8, 16, 1, 'n');
});

// ---------- wallpapers (16x16, tile horizontally, baseboard at bottom) ----------
const base = (s) => {
  f(s, 0, 13, 16, 1, 'b');
  f(s, 0, 14, 16, 1, 'c');
  f(s, 0, 15, 16, 1, 'd');
};
sprites['wallpaper.cream'] = mk(16, 16, (s) => {
  f(s, 0, 0, 16, 13, 'a');
  f(s, 0, 0, 1, 13, 'b');
  f(s, 8, 0, 1, 13, 'b');
  base(s);
});
sprites['wallpaper.pink'] = mk(16, 16, (s) => {
  f(s, 0, 0, 16, 13, 'm');
  for (const x of [0, 4, 8, 12]) f(s, x, 0, 1, 13, 'n');
  for (const x of [2, 6, 10, 14]) for (let y = 1; y < 13; y += 4) p(s, x, y, 'W');
  base(s);
});
sprites['wallpaper.flowers'] = mk(16, 16, (s) => {
  f(s, 0, 0, 16, 13, 'a');
  const fl = (cx, cy) => {
    p(s, cx, cy - 1, 'n'); p(s, cx, cy + 1, 'n'); p(s, cx - 1, cy, 'n'); p(s, cx + 1, cy, 'n');
    p(s, cx, cy, 'b');
    p(s, cx + 2, cy + 2, 'h');
  };
  fl(3, 3); fl(11, 8);
  p(s, 11, 2, 'h'); p(s, 3, 9, 'h');
  base(s);
});
sprites['wallpaper.leaves'] = mk(16, 16, (s) => {
  f(s, 0, 0, 16, 13, 'g');
  const lf = (x, y) => { p(s, x, y, 'i'); p(s, x + 1, y, 'h'); p(s, x + 1, y + 1, 'i'); p(s, x + 2, y + 1, 'h'); p(s, x, y + 1, 'j'); };
  lf(1, 1); lf(9, 4); lf(4, 8); lf(12, 10); lf(13, 0);
  base(s);
});
sprites['wallpaper.checker'] = mk(16, 16, (s) => {
  for (let y = 0; y < 13; y++) for (let x = 0; x < 16; x++) p(s, x, y, ((x >> 2) + (y >> 2)) % 2 ? 'm' : 'a');
  base(s);
});
sprites['wallpaper.stars'] = mk(16, 16, (s) => {
  f(s, 0, 0, 16, 13, 'w');
  f(s, 0, 0, 16, 1, 'v');
  const st = (x, y) => { p(s, x, y, 'W'); p(s, x - 1, y, 'a'); p(s, x + 1, y, 'a'); p(s, x, y - 1, 'a'); p(s, x, y + 1, 'a'); };
  st(3, 4); st(11, 8);
  p(s, 9, 2, 'a'); p(s, 14, 5, 'a'); p(s, 1, 10, 'a'); p(s, 6, 11, 'a');
  base(s);
});

// ---------- wall trim and corners ----------
sprites['wall.trim'] = mk(16, 16, (s) => {
  f(s, 0, 0, 16, 1, 'O');
  f(s, 0, 1, 16, 1, 'b');
  f(s, 0, 2, 16, 2, 'c');
  f(s, 0, 4, 16, 1, 'd');
  f(s, 0, 5, 16, 1, 'O');
});
const corner = (right) => mk(16, 16, (s) => {
  f(s, 0, 0, 16, 1, 'O');
  f(s, 0, 1, 16, 1, 'b');
  f(s, 0, 2, 16, 2, 'c');
  f(s, 0, 4, 16, 1, 'd');
  const x0 = right ? 12 : 0;
  f(s, x0, 0, 4, 16, 'O');
  f(s, x0 + 1, 1, 2, 15, 'c');
  f(s, right ? x0 + 1 : x0 + 2, 1, 1, 15, 'b');
  f(s, right ? x0 + 2 : x0 + 1, 1, 1, 15, 'd');
  f(s, right ? 0 : 4, 5, right ? 12 : 12, 1, 'O');
});
sprites['wall.corner.l'] = corner(false);
sprites['wall.corner.r'] = corner(true);

// ---------- furniture ----------
const F = (name, s) => { sprites['furn.' + name] = out(s); };
const FV = (id, s) => { sprites[id] = out(s); };

const deskBase = (s) => {
  ob(s, 0, 7, 32, 5, 'c', 'b', 'd');
  ob(s, 2, 11, 4, 5, 'd', 'c', 'e');
  ob(s, 26, 11, 4, 5, 'd', 'c', 'e');
  ob(s, 8, 11, 16, 2, 'd');
};
const pot = (s) => {
  ob(s, 25, 3, 5, 5, 'q', 'r', 'r');
  p(s, 26, 1, 'o'); p(s, 26, 2, 'O'); p(s, 28, 0, 'u'); p(s, 28, 1, 'u'); p(s, 28, 2, 'O'); p(s, 27, 2, 'O');
};
F('desk', (() => {
  const s = G(32, 16);
  deskBase(s);
  ob(s, 6, 0, 12, 7, 'v');
  f(s, 7, 1, 10, 4, 'u');
  f(s, 8, 2, 3, 1, 't');
  f(s, 9, 6, 8, 1, 'O');
  pot(s);
  return s;
})());
F('desk.study', (() => {
  const s = G(32, 16);
  deskBase(s);
  ob(s, 3, 0, 12, 7, 'v');
  f(s, 4, 1, 10, 4, 's');
  f(s, 5, 2, 4, 1, 'W');
  f(s, 5, 3, 6, 1, 't');
  // open book
  ob(s, 17, 4, 9, 4, 'W');
  f(s, 21, 5, 1, 2, 'b');
  f(s, 18, 5, 2, 1, 't'); f(s, 23, 5, 2, 1, 't');
  f(s, 18, 6, 2, 1, 'n'); f(s, 23, 6, 2, 1, 'n');
  pot(s);
  return s;
})());

F('chair', (() => {
  const s = G(16, 16);
  ob(s, 4, 1, 8, 7, 'c', 'b', 'd');
  f(s, 6, 3, 4, 3, 'b');
  ob(s, 3, 8, 10, 3, 'o', 'n', 'p');
  ob(s, 4, 11, 2, 5, 'd');
  ob(s, 10, 11, 2, 5, 'd');
  return s;
})());

F('bed', (() => {
  const s = G(32, 32);
  ob(s, 0, 0, 32, 9, 'd', 'c', 'e');
  f(s, 2, 3, 28, 1, 'c');
  ob(s, 1, 7, 30, 24, 'a');
  ob(s, 3, 9, 11, 7, 'W', 'W', 's');
  ob(s, 18, 9, 11, 7, 'W', 'W', 's');
  ob(s, 1, 16, 30, 15, 'n', 'm', 'o');
  f(s, 2, 19, 28, 1, 'm');
  for (let x = 4; x < 28; x += 6) { p(s, x, 23, 'm'); p(s, x + 1, 23, 'm'); p(s, x, 24, 'm'); p(s, x + 1, 24, 'm'); }
  f(s, 2, 27, 28, 1, 'o');
  ob(s, 0, 30, 4, 2, 'd');
  ob(s, 28, 30, 4, 2, 'd');
  return s;
})());

F('bookshelf', (() => {
  const s = G(16, 32);
  ob(s, 0, 0, 16, 32, 'd', 'c', 'e');
  const cols = ['o', 'u', 'h', 'q', 'b', 'n', 'v'];
  for (let r = 0; r < 3; r++) {
    const y = 2 + r * 10;
    f(s, 2, y, 12, 8, 'e');
    f(s, 2, y + 8, 12, 1, 'O');
    let x = 2;
    let i = r * 2;
    while (x < 13) {
      const w = 2 + ((x + r) % 2);
      const hh = 5 + ((x + r * 3) % 3);
      if (x + w > 14) break;
      f(s, x, y + 8 - hh, w, hh, cols[i++ % cols.length]);
      p(s, x, y + 8 - hh, 'W');
      x += w;
    }
  }
  return s;
})());

F('rug', (() => {
  const s = G(32, 16);
  ob(s, 0, 0, 32, 16, 'p');
  f(s, 2, 2, 28, 12, 'm');
  f(s, 3, 3, 26, 10, 'n');
  for (let x = 6; x < 26; x += 4) { p(s, x, 8, 'W'); p(s, x + 1, 7, 'm'); p(s, x + 1, 9, 'm'); }
  for (let x = 1; x < 31; x += 2) { p(s, x, 1, 'o'); p(s, x, 14, 'o'); }
  return s;
})());

F('plant', (() => {
  const s = G(16, 16);
  odisc(s, 8, 5, 4, 'i');
  odisc(s, 5, 7, 3, 'h');
  odisc(s, 11, 7, 3, 'h');
  disc(s, 8, 4, 2, 'g');
  ob(s, 4, 10, 8, 6, 'c', 'b', 'd');
  f(s, 3, 10, 10, 1, 'O'); f(s, 4, 10, 8, 1, 'd');
  return s;
})());

const lamp = (lit) => {
  const s = G(16, 24);
  if (lit) {
    f(s, 1, 0, 14, 1, '.');
    for (const [x, y] of [[1, 1], [14, 1], [0, 5], [15, 5], [2, 8], [13, 8], [0, 3], [15, 3]]) p(s, x, y, 'a');
  }
  const shade = lit ? 'a' : 'm';
  ob(s, 3, 2, 10, 2, 'O');
  for (let y = 0; y < 8; y++) {
    const x0 = 5 - Math.floor(y * 0.5), x1 = 10 + Math.floor(y * 0.5);
    f(s, x0 - 1, 3 + y, x1 - x0 + 3, 1, 'O');
    f(s, x0, 3 + y, x1 - x0 + 1, 1, y < 2 ? (lit ? 'W' : 'W') : shade);
  }
  f(s, 4, 11, 8, 1, 'O');
  f(s, 7, 12, 2, 8, 'O'); f(s, 7, 12, 1, 8, 'c'); f(s, 8, 12, 1, 8, 'd');
  ob(s, 4, 20, 8, 4, 'd', 'c', 'e');
  return s;
};
F('lamp', lamp(false));
FV('furn.lamp.lit', lamp(true));

F('window', (() => {
  const s = G(16, 16);
  ob(s, 1, 1, 14, 14, 'c');
  f(s, 3, 3, 10, 10, 'O');
  f(s, 4, 4, 4, 4, 's'); f(s, 9, 4, 3, 4, 's'); f(s, 4, 9, 4, 3, 's'); f(s, 9, 9, 3, 3, 's');
  f(s, 4, 4, 2, 1, 'W'); f(s, 9, 4, 2, 1, 'W');
  p(s, 5, 10, 'W'); p(s, 10, 10, 'W');
  f(s, 4, 7, 4, 1, 't'); f(s, 9, 7, 3, 1, 't');
  f(s, 0, 14, 16, 2, 'O'); f(s, 0, 14, 16, 1, 'b');
  return s;
})());
sprites['window.beam'] = mk(16, 16, (s) => {
  for (let y = 0; y < 16; y++) for (let x = 0; x < 16; x++) {
    const d = (x + y) % 8;
    if (d === 0 || d === 1) p(s, x, y, d === 0 ? 'a' : 'W');
  }
  for (let x = 0; x < 16; x++) for (let y = 0; y < 16; y++) if (((x + y) % 8 === 4) && (x + y) % 2 === 0 && y % 4 === 0) p(s, x, y, 'a');
});

F('poster', (() => {
  const s = G(16, 16);
  ob(s, 3, 1, 10, 14, 'W');
  f(s, 4, 2, 8, 9, 's');
  disc(s, 9, 5, 1, 'a'); p(s, 9, 5, 'b');
  f(s, 4, 8, 8, 3, 'h');
  f(s, 4, 8, 4, 1, 'g');
  f(s, 5, 12, 6, 1, 'n'); f(s, 6, 13, 4, 1, 't');
  return s;
})());

const petbed = (cat) => {
  const s = G(16, 16);
  ob(s, 1, 7, 14, 8, 'p', 'o', 'q');
  f(s, 3, 8, 10, 4, 'm');
  f(s, 3, 8, 10, 1, 'W');
  if (cat) {
    odisc(s, 8, 8, 4, 'c');
    f(s, 4, 4, 2, 2, 'O'); f(s, 10, 4, 2, 2, 'O');
    p(s, 4, 5, 'n'); p(s, 11, 5, 'n');
    f(s, 5, 7, 6, 1, 'b');
    p(s, 6, 8, 'O'); p(s, 7, 8, 'O'); p(s, 9, 8, 'O'); p(s, 10, 8, 'O');
    p(s, 8, 9, 'n');
    f(s, 6, 11, 5, 1, 'd');
    ob(s, 1, 11, 14, 4, 'p', 'o', 'q');
  } else {
    f(s, 3, 10, 10, 1, 'n');
  }
  return s;
};
F('petbed', petbed(false));
FV('furn.petbed.cat', petbed(true));

F('globe', (() => {
  const s = G(16, 16);
  ob(s, 4, 13, 8, 3, 'd', 'c', 'e');
  f(s, 7, 11, 2, 3, 'O');
  odisc(s, 8, 6, 5, 'u');
  f(s, 5, 4, 3, 2, 'h'); f(s, 8, 3, 2, 3, 'h'); f(s, 7, 8, 3, 2, 'h'); p(s, 11, 7, 'h');
  f(s, 5, 2, 2, 1, 's'); p(s, 4, 3, 's');
  return s;
})());

F('books', (() => {
  const s = G(16, 16);
  ob(s, 2, 11, 12, 4, 'o', 'n', 'p');
  ob(s, 3, 7, 10, 4, 'u', 't', 'v');
  ob(s, 2, 3, 11, 4, 'h', 'g', 'i');
  f(s, 4, 12, 1, 2, 'a'); f(s, 5, 8, 1, 2, 'a'); f(s, 4, 4, 1, 2, 'a');
  return s;
})());

F('clock', (() => {
  const s = G(16, 16);
  odisc(s, 8, 8, 6, 'c');
  disc(s, 8, 8, 5, 'W');
  p(s, 8, 4, 'O'); p(s, 8, 12, 'O'); p(s, 4, 8, 'O'); p(s, 12, 8, 'O');
  f(s, 8, 5, 1, 4, 'O'); f(s, 9, 8, 2, 1, 'o');
  p(s, 8, 8, 'O');
  return s;
})());

const candle = (fr) => {
  const s = G(16, 16);
  ob(s, 3, 13, 10, 3, 'c', 'b', 'd');
  ob(s, 6, 7, 4, 7, 'a', 'W', 'b');
  p(s, 7, 6, 'O');
  if (fr === 0) { f(s, 7, 3, 2, 3, 'o'); p(s, 7, 4, 'b'); p(s, 8, 4, 'b'); p(s, 7, 5, 'a'); p(s, 8, 5, 'a'); p(s, 7, 2, 'o'); }
  else { f(s, 7, 4, 2, 2, 'o'); p(s, 8, 3, 'o'); p(s, 9, 2, 'o'); p(s, 7, 4, 'b'); p(s, 7, 5, 'a'); p(s, 8, 5, 'a'); }
  return s;
};
F('candle', candle(0));
FV('furn.candle.1', candle(1));
anims.candle = { id: 'candle', frames: ['furn.candle', 'furn.candle.1'], fps: 4, loop: true };

F('stool', (() => {
  const s = G(16, 16);
  ob(s, 3, 6, 10, 4, 'c', 'b', 'd');
  ob(s, 4, 10, 2, 6, 'd'); ob(s, 10, 10, 2, 6, 'd');
  f(s, 5, 13, 6, 1, 'O');
  return s;
})());

F('beanbag', (() => {
  const s = G(16, 16);
  odisc(s, 8, 10, 5, 'q');
  odisc(s, 8, 8, 4, 'q');
  f(s, 3, 13, 11, 1, 'r');
  f(s, 5, 6, 4, 1, 'o'); p(s, 4, 8, 'o'); f(s, 6, 7, 2, 1, 'm');
  p(s, 5, 7, 'm'); p(s, 4, 9, 'm');
  return s;
})());

F('cushion', (() => {
  const s = G(16, 16);
  ob(s, 3, 4, 10, 9, 'n', 'm', 'o');
  p(s, 2, 3, 'O'); p(s, 13, 3, 'O'); p(s, 2, 13, 'O'); p(s, 13, 13, 'O');
  p(s, 8, 8, 'p'); p(s, 7, 8, 'm'); p(s, 9, 8, 'm'); p(s, 8, 7, 'm'); p(s, 8, 9, 'm');
  return s;
})());

F('catplush', (() => {
  const s = G(16, 16);
  odisc(s, 8, 11, 4, 'a');
  odisc(s, 8, 6, 4, 'a');
  f(s, 4, 1, 3, 3, 'O'); f(s, 9, 1, 3, 3, 'O');
  p(s, 5, 2, 'n'); p(s, 10, 2, 'n'); p(s, 5, 3, 'a'); p(s, 10, 3, 'a');
  f(s, 6, 3, 4, 1, 'a');
  p(s, 6, 6, 'E'); p(s, 10, 6, 'E'); p(s, 5, 8, 'B'); p(s, 11, 8, 'B');
  p(s, 8, 8, 'n'); p(s, 7, 9, 'O'); p(s, 9, 9, 'O');
  f(s, 5, 12, 6, 1, 'b'); p(s, 13, 12, 'O'); p(s, 13, 11, 'b');
  return s;
})());

F('chest', (() => {
  const s = G(16, 16);
  ob(s, 1, 8, 14, 7, 'd', 'c', 'e');
  ob(s, 1, 3, 14, 6, 'c', 'b', 'd');
  f(s, 3, 3, 1, 12, 'O'); f(s, 12, 3, 1, 12, 'O');
  f(s, 3, 4, 1, 4, 'a'); f(s, 12, 4, 1, 4, 'a');
  ob(s, 6, 7, 4, 4, 'b'); p(s, 7, 9, 'O'); p(s, 8, 9, 'O');
  return s;
})());

const lights = (on) => {
  const s = G(32, 16);
  const ys = [3, 5, 6, 5, 3, 5, 6, 5];
  for (let x = 0; x < 32; x++) {
    const y = 2 + Math.round(3 * Math.sin((x / 32) * Math.PI * 4 + 0.6) + 3);
    p(s, x, Math.min(y, 8) - 1, 'e');
  }
  const cs = ['n', 'a', 'h', 't'];
  [3, 11, 19, 27].forEach((x, i) => {
    const wy = 2 + Math.round(3 * Math.sin((x / 32) * Math.PI * 4 + 0.6) + 3);
    const y = Math.min(wy, 8);
    const lit = (i % 2) === on;
    p(s, x, y, 'O'); p(s, x, y + 1, lit ? cs[i] : 'O');
    f(s, x - 1, y + 2, 3, 3, 'O');
    f(s, x, y + 2, 1, 2, lit ? 'W' : cs[i]);
    p(s, x + 1, y + 3, cs[i]);
    p(s, x, y + 4, 'O');
    if (lit) { p(s, x - 2, y + 3, cs[i]); p(s, x + 2, y + 3, cs[i]); p(s, x, y + 5, cs[i]); p(s, x - 1, y + 5, 'W'); }
  });
  void ys;
  return s;
};
F('stringlights', lights(0));
FV('furn.stringlights.1', lights(1));
anims.stringlights = { id: 'stringlights', frames: ['furn.stringlights', 'furn.stringlights.1'], fps: 2, loop: true };

F('frame', (() => {
  const s = G(16, 16);
  ob(s, 2, 2, 12, 12, 'c', 'b', 'd');
  f(s, 4, 4, 8, 8, 'O');
  f(s, 5, 5, 6, 6, 's');
  f(s, 5, 9, 6, 2, 'h');
  disc(s, 9, 7, 1, 'a');
  p(s, 6, 8, 'g');
  return s;
})());

F('guitar', (() => {
  const s = G(16, 32);
  ob(s, 6, 0, 4, 5, 'e', 'd', 'f');
  p(s, 5, 1, 'a'); p(s, 10, 1, 'a'); p(s, 5, 3, 'a'); p(s, 10, 3, 'a');
  f(s, 7, 5, 2, 10, 'O'); f(s, 7, 5, 1, 10, 'd'); f(s, 8, 5, 1, 10, 'e');
  odisc(s, 8, 18, 4, 'c');
  odisc(s, 8, 25, 6, 'c');
  disc(s, 8, 25, 5, 'c');
  disc(s, 7, 23, 3, 'b');
  disc(s, 8, 24, 2, 'O');
  f(s, 5, 29, 7, 1, 'd');
  f(s, 6, 28, 5, 1, 'd');
  f(s, 7, 15, 1, 12, 'a');
  return s;
})());

F('bigplant', (() => {
  const s = G(16, 32);
  odisc(s, 8, 8, 6, 'i');
  odisc(s, 4, 13, 4, 'h');
  odisc(s, 12, 13, 4, 'h');
  odisc(s, 8, 15, 4, 'i');
  disc(s, 7, 5, 3, 'h');
  disc(s, 6, 4, 1, 'g');
  disc(s, 3, 12, 1, 'g'); disc(s, 11, 12, 1, 'g');
  p(s, 8, 12, 'j'); p(s, 8, 14, 'j'); p(s, 6, 16, 'j'); p(s, 10, 16, 'j');
  f(s, 7, 19, 2, 4, 'O'); f(s, 7, 19, 1, 4, 'i');
  ob(s, 3, 22, 10, 10, 'c', 'b', 'd');
  f(s, 2, 22, 12, 1, 'O'); f(s, 3, 22, 10, 1, 'd');
  f(s, 4, 25, 8, 1, 'd');
  return s;
})());

const tank = (fr) => {
  const s = G(32, 16);
  ob(s, 0, 1, 32, 13, 's');
  f(s, 1, 2, 30, 11, 't');
  f(s, 1, 2, 30, 1, 's');
  f(s, 1, 11, 30, 2, 'a');
  f(s, 2, 12, 2, 1, 'b'); f(s, 12, 12, 2, 1, 'b');
  // plants
  f(s, 25, 6, 1, 5, 'i'); f(s, 27, 5, 1, 6, 'h'); p(s, 26, 6, 'h'); p(s, 26, 7, 'i');
  // fish
  const fx = fr ? 12 : 9;
  f(s, fx, 6, 4, 3, 'o');
  p(s, fx - 1, fr ? 7 : 6, 'o'); p(s, fx - 1, fr ? 8 : 7, 'o'); p(s, fx + 4, 7, 'o'); p(s, fx + 4, fr ? 6 : 8, 'o');
  p(s, fx + 2, 6, 'b'); p(s, fx + 3, 7, 'E'); p(s, fx + 1, 8, 'b');
  const fx2 = fr ? 6 : 4;
  f(s, fx2, 3, 3, 2, 'u'); p(s, fx2 + 3, fr ? 3 : 4, 'u');
  // bubbles
  const by = fr ? 0 : 2;
  p(s, 19, 8 - by, 'W'); p(s, 20, 5 - by, 'W'); p(s, 19, 3 + (fr ? 0 : 1) , 'W');
  p(s, 22, 9 - by, 's');
  f(s, 0, 14, 32, 1, 'O');
  ob(s, 1, 14, 30, 2, 'd', 'c', 'e');
  return s;
};
F('fishtank', tank(0));
FV('furn.fishtank.1', tank(1));
anims.fishtank = { id: 'fishtank', frames: ['furn.fishtank', 'furn.fishtank.1'], fps: 2, loop: true };

// ---------- meta ----------
const sz = (name, wall = false) => {
  const s = sprites['furn.' + name];
  return { w: Math.ceil(s.w / 16), h: Math.ceil(s.h / 16), wall };
};
const furniture = {};
for (const n of ['desk', 'chair', 'bed', 'bookshelf', 'rug', 'plant', 'lamp', 'petbed', 'globe', 'books', 'candle', 'stool', 'beanbag', 'cushion', 'catplush', 'chest', 'guitar', 'bigplant', 'fishtank']) furniture[n] = sz(n);
for (const n of ['window', 'poster', 'clock', 'frame', 'stringlights']) furniture[n] = sz(n, true);

export default { sprites, anims, meta: { furniture } };
